import sys


class DigitSum:
    def __init__(self, number: int):
        self.digit_sum = sum(int(d) for d in str(abs(number)))

    @staticmethod
    def total(objects) -> int:
        return sum(obj.digit_sum for obj in objects)


def main() -> None:
    data = sys.stdin.read().split()
    numbers = [int(x) for x in data[:3]]
    objects = [DigitSum(n) for n in numbers]
    print(DigitSum.total(objects))


if __name__ == "__main__":
    main()
